#!/usr/bin/env bash

# Generated by gpipe - DO NOT EDIT MANUALLY!
# GitHub: https://github.com/thomaslaurenson/gpipe
# Version: {{.Version}}

# Re-generate with:
# gpipe generate --repo <owner/repo> --version <vX.Y.Z>

# Wrapping the script body in a brace block causes the shell to buffer the
# complete download before starting execution, preventing partial runs if the
# connection drops mid-pipe.
{
# set -euo pipefail is intentionally inside the brace block so it applies
# only after the download guard is established.
set -euo pipefail

# CONSTANTS: baked in at generation time
readonly GITHUB_REPO="{{.GithubRepo}}"
readonly VERSION="{{.Version}}"
readonly BINARY="{{.Binary}}"
readonly INSTALL_NAME="{{.InstallName}}"

# OUTPUT HELPERS
# Check stdout (fd 1) for colour support
if [[ -t 1 ]] && [[ -z "${NO_COLOR:-}" ]] && [[ "${TERM:-}" != "dumb" ]]; then
  _RED='\033[0;31m' _GREEN='\033[0;32m' _YELLOW='\033[1;33m'
  _CYAN='\033[0;36m' _BOLD='\033[1m' _NC='\033[0m'
else
  _RED='' _GREEN='' _YELLOW='' _CYAN='' _BOLD='' _NC=''
fi

info()  { printf "${_GREEN}[INFO]${_NC}  %s\n" "$1"; }
warn()  { printf "${_YELLOW}[WARN]${_NC}  %s\n" "$1" >&2; }
error() { printf "${_RED}[ERROR]${_NC} %s\n" "$1" >&2; exit 1; }
step()  { printf "  ${_CYAN}>${_NC} %s\n" "$1"; }

# Print help message to stdout.
show_help() {
  cat <<EOF
${_BOLD}${INSTALL_NAME} installer${_NC}

USAGE:
  bash install.sh [OPTIONS]

OPTIONS:
  -h, --help      Show this help message
  --user          Install to ~/.local/bin (no sudo required)
  --system        Install to /usr/local/bin (default, may require sudo)
  --no-verify     Skip cosign signature verification on checksums.txt
                  By default, the installer verifies the release signature
                  using cosign. Use this flag only if cosign is unavailable.
                  Install cosign:
                  https://docs.sigstore.dev/cosign/system_config/installation/

EXAMPLES:
  # System-wide install (default)
  curl -fsSL \
    https://github.com/${GITHUB_REPO}/releases/download/${VERSION}/install.sh \
    | bash

  # User-local install, no sudo needed
  curl -fsSL \
    https://github.com/${GITHUB_REPO}/releases/download/${VERSION}/install.sh \
    | bash -s -- --user

  # Skip cosign verification (not recommended)
  curl -fsSL \
    https://github.com/${GITHUB_REPO}/releases/download/${VERSION}/install.sh \
    | bash -s -- --no-verify
EOF
}

# Parse command-line arguments and set USER_INSTALL and NO_VERIFY.
#
# Arguments:
#   $@ - command-line arguments
# Environment:
#   USER_INSTALL - set to true for --user, false for --system
#   NO_VERIFY    - set to true when --no-verify is passed
# Returns:
#   0 on success
#   exits 1 for unknown options
parse_args() {
  while [[ $# -gt 0 ]]; do
    case "$1" in
      -h|--help)    show_help; exit 0 ;;
      --user)       USER_INSTALL=true;  shift ;;
      --system)     USER_INSTALL=false; shift ;;
      --no-verify)  NO_VERIFY=true;     shift ;;
      *)            error "Unknown option: $1. Run with --help for usage." ;;
    esac
  done
}

# Detect the current OS and architecture and print a platform identifier.
#
# Outputs:
#   stdout: platform string, e.g. linux_amd64 or darwin_arm64
# Returns:
#   0 on success
#   exits 1 for unsupported OS or architecture
detect_platform() {
  local os arch
  local _os _arch
  _os="$(uname -s)"
  _arch="$(uname -m)"

  case "$_os" in
    Linux)  os="linux"  ;;
    Darwin) os="darwin" ;;
    *)      error "Unsupported operating system: ${_os}" ;;
  esac

  case "$_arch" in
    x86_64)        arch="amd64" ;;
    aarch64|arm64) arch="arm64" ;;
    *)             error "Unsupported architecture: ${_arch}" ;;
  esac

  printf '%s_%s' "$os" "$arch"
}

# Resolve the release asset filename for a given platform identifier.
#
# Arguments:
#   $1 - platform string, e.g. linux_amd64
# Outputs:
#   stdout: asset filename, e.g. mytool_linux_amd64
# Returns:
#   0 on success
#   exits 1 for unsupported platform
resolve_asset() {
  local platform="$1"
  case "$platform" in
{{- range .Platforms}}
    {{.ID}}) printf '%s' "{{.AssetName}}" ;;
{{- end}}
    *)
      local supported
      supported="$(printf '%s ' '{{range .Platforms}}{{.ID}} {{end}}')"
      error "Unsupported platform: ${platform}. Supported: ${supported}"
      ;;
  esac
}

# Initialise the _download function, preferring curl over wget.
#
# Defines _download as a function in the current shell. Exits with an error
# if neither curl nor wget is available.
#
# Returns:
#   0 on success
#   exits 1 if neither curl nor wget is found
setup_downloader() {
  if command -v curl > /dev/null 2>&1; then
    _download() {
      curl -fsSL --connect-timeout 30 --speed-limit 1024 --speed-time 30 "$1" -o "$2"
    }
  elif command -v wget > /dev/null 2>&1; then
    _download() {
      wget --connect-timeout=30 --timeout=30 -qO "$2" "$1"
    }
  else
    error "curl or wget is required to download files"
  fi
}

# Download the binary, checksums, and cosign bundle into a temp directory.
#
# Arguments:
#   $1 - destination directory (must already exist)
#   $2 - asset filename
# Environment:
#   GITHUB_REPO, VERSION - used to construct download URLs
# Returns:
#   0 on success
#   exits 1 if any download fails
download_assets() {
  local dest_dir="$1"
  local asset_name="$2"
  local base_url
  base_url="https://github.com/${GITHUB_REPO}/releases/download/${VERSION}"
  local download_url="${base_url}/${asset_name}"
  local checksums_url="${base_url}/checksums.txt"
  local checksums_sig_url="${base_url}/checksums.txt.sigstore.json"

  info "Downloading ${BINARY} ${VERSION} for ${PLATFORM}..."
  step "${download_url}"
  _download "${download_url}"       "${dest_dir}/${asset_name}"
  _download "${checksums_url}"      "${dest_dir}/checksums.txt"
  _download "${checksums_sig_url}"  "${dest_dir}/checksums.txt.sigstore.json"
}

# Verify the cosign signature on checksums.txt.
#
# Skips verification when NO_VERIFY is true. Exits with an error if cosign
# is not found and NO_VERIFY is false.
#
# Arguments:
#   $1 - directory containing checksums.txt and checksums.txt.sigstore.json
# Environment:
#   NO_VERIFY   - skip when true
#   GITHUB_REPO - used to build the certificate identity regexp
#   VERSION     - used in the skip warning message
# Returns:
#   0 on success or when skipped
#   exits 1 if cosign is missing or verification fails
verify_signature() {
  local dir="$1"

  if [[ "${NO_VERIFY}" == "true" ]]; then
    warn "Skipping cosign signature verification (--no-verify passed)"
    return 0
  fi

  if ! command -v cosign > /dev/null 2>&1; then
    error "cosign not found in PATH.

  The installer verifies release signatures by default to ensure
  the download has not been tampered with. cosign is required for this.

  Install cosign: https://docs.sigstore.dev/cosign/system_config/installation/

  To skip verification (not recommended) pass following arguments:
    bash -s -- --no-verify"
  fi

  info "Verifying cosign signature on checksums.txt..."
  local cert_identity
  cert_identity="https://github.com/{{.GithubRepo}}/.github/workflows/.*"
  cosign verify-blob \
    --bundle "${dir}/checksums.txt.sigstore.json" \
    --certificate-identity-regexp="${cert_identity}" \
    --certificate-oidc-issuer="https://token.actions.githubusercontent.com" \
    "${dir}/checksums.txt" || error "cosign signature verification failed"
  step "Cosign signature OK"
}

# Verify the SHA-256 checksum of a downloaded asset.
#
# Arguments:
#   $1 - directory containing both the asset and checksums.txt
#   $2 - asset filename to verify
# Returns:
#   0 when the checksum matches
#   exits 1 if sha256sum/shasum is missing, the entry is not found, or the
#   hash does not match
verify_checksum() {
  local dir="$1"
  local asset_name="$2"
  local expected_hash actual_hash

  info "Verifying checksum..."

  expected_hash="$(grep -F "  ${asset_name}" "${dir}/checksums.txt" | awk '{print $1}')"
  if [[ -z "${expected_hash}" ]]; then
    error "Checksum not found for ${asset_name} in checksums.txt"
  fi

  if command -v sha256sum > /dev/null 2>&1; then
    actual_hash="$(sha256sum "${dir}/${asset_name}" | awk '{print $1}')"
  elif command -v shasum > /dev/null 2>&1; then
    actual_hash="$(shasum -a 256 "${dir}/${asset_name}" | awk '{print $1}')"
  else
    error "sha256sum or shasum is required to verify checksums but was not found in PATH"
  fi

  if [[ "${expected_hash}" != "${actual_hash}" ]]; then
    error "Checksum mismatch for ${asset_name}
  expected: ${expected_hash}
  actual:   ${actual_hash}"
  fi
  step "Checksum OK"
}

# Attempt to install a binary to a directory.
#
# Uses install(1) when available, falling back to cp + chmod for minimal
# environments. Returns non-zero on permission failure without exiting, so
# the caller can handle the fallback.
#
# Arguments:
#   $1 - source file path
#   $2 - destination directory
#   $3 - destination filename
# Returns:
#   0 on success
#   non-zero on failure (permission denied or install error)
_try_install() {
  local src="$1" dir="$2" name="$3"
  mkdir -p "$dir" 2>/dev/null || true
  if command -v install > /dev/null 2>&1; then
    install -m 0755 "$src" "${dir}/${name}"
  else
    cp "$src" "${dir}/${name}" && chmod 0755 "${dir}/${name}"
  fi
}

# Install the binary to the resolved install directory.
#
# For system installs, falls back to a sudo prompt when permissions are
# insufficient. In non-interactive (no TTY) mode, prints instructions and
# exits rather than prompting.
#
# Arguments:
#   $1 - source file path (downloaded binary in tmp dir)
# Environment:
#   USER_INSTALL  - true for user install, false for system install
#   INSTALL_NAME  - destination filename
#   INSTALL_DIR   - set by this function to the chosen install path
#   GITHUB_REPO, VERSION - used in no-TTY error messages
# Returns:
#   0 on success
#   exits 1 on failure
install_binary() {
  local src="$1"

  if [[ "${USER_INSTALL}" == "true" ]]; then
    local user_dir="${HOME}/.local/bin"
    _try_install "${src}" "${user_dir}" "${INSTALL_NAME}" \
      || error "Failed to install to ${user_dir}: check directory permissions"
    INSTALL_DIR="${user_dir}"
  else
    local sys_dir="/usr/local/bin"
    if _try_install "${src}" "${sys_dir}" "${INSTALL_NAME}" 2>/dev/null; then
      INSTALL_DIR="${sys_dir}"
    else
      if [[ -t 2 ]]; then
        printf "\n${_YELLOW}Insufficient permissions to install to %s.${_NC}\n\n" "${sys_dir}" >&2
        printf "  1) Retry with sudo\n" >&2
        printf "  2) Install to ~/.local/bin (no sudo required)\n" >&2
        printf "  3) Quit\n\n" >&2
        read -rp "Choose [1/2/3]: " _choice </dev/tty
        case "${_choice}" in
          1)
            info "Retrying with sudo..."
            sudo install -m 0755 "${src}" "${sys_dir}/${INSTALL_NAME}" \
              || error "sudo install failed"
            INSTALL_DIR="${sys_dir}"
            ;;
          2)
            USER_INSTALL=true
            local user_dir="${HOME}/.local/bin"
            _try_install "${src}" "${user_dir}" "${INSTALL_NAME}" \
              || error "Failed to install to ${user_dir}: check directory permissions"
            INSTALL_DIR="${user_dir}"
            ;;
          *)
            error "Installation aborted." ;;
        esac
      else
        local install_url
        install_url="https://github.com/${GITHUB_REPO}"
        install_url+="/releases/download/${VERSION}/install.sh"
        printf "\n%s[ERROR]%s Insufficient permissions" "${_RED}" "${_NC}" >&2
        printf " to install to %s\n\n" "${sys_dir}" >&2
        printf "To retry as root:\n" >&2
        printf "  sudo bash <(curl -fsSL %s)\n\n" "${install_url}" >&2
        printf "To install without sudo (user install):\n" >&2
        printf "  curl -fsSL %s | bash -s -- --user\n" "${install_url}" >&2
        exit 1
      fi
    fi
  fi

  info "Installed ${INSTALL_NAME} to ${INSTALL_DIR}/${INSTALL_NAME}"
}

{{- if .Completions.Bash}}
# gpipe test: bash-completions

# Install bash completions generated by the installed binary.
#
# Falls back to the user completion directory when system install fails.
#
# Environment:
#   INSTALL_DIR, INSTALL_NAME, BINARY, USER_INSTALL - read
# Returns:
#   0 always (warns on failure)
install_bash_completions() {
  local completion
  if ! completion=$("${INSTALL_DIR}/${INSTALL_NAME}" completion bash 2>/dev/null); then
    warn "Bash completion not available from ${INSTALL_NAME}"
    warn "Binary may not support the completion subcommand"
    return 0
  fi

  if [[ "${USER_INSTALL}" == "true" ]]; then
    mkdir -p "${HOME}/.bash_completion.d"
    printf '%s\n' "${completion}" > "${HOME}/.bash_completion.d/${BINARY}"
    step "Bash completions -> ~/.bash_completion.d/${BINARY}"
  elif printf '%s\n' "${completion}" \
      | sudo install -m 0644 /dev/stdin \
          "/etc/bash_completion.d/${BINARY}" 2>/dev/null; then
    step "Bash completions -> /etc/bash_completion.d/${BINARY}"
  else
    mkdir -p "${HOME}/.bash_completion.d"
    printf '%s\n' "${completion}" > "${HOME}/.bash_completion.d/${BINARY}"
    step "Bash completions -> ~/.bash_completion.d/${BINARY}"
  fi
}
{{- end}}
{{- if .Completions.Zsh}}
# gpipe test: zsh-completions

# Install zsh completions generated by the installed binary.
#
# Falls back to the user completion directory when system install fails.
#
# Environment:
#   INSTALL_DIR, INSTALL_NAME, BINARY, USER_INSTALL - read
# Returns:
