  if [[ "${USER_INSTALL}" == "true" ]]; then
    mkdir -p "${HOME}/.zfunc"
    printf '%s\n' "${completion}" > "${HOME}/.zfunc/_${BINARY}"
    step "Zsh completions -> ~/.zfunc/_${BINARY}"
  elif printf '%s\n' "${completion}" \
      | sudo install -m 0644 /dev/stdin \
          "/usr/share/zsh/site-functions/_${BINARY}" 2>/dev/null; then
    step "Zsh completions -> /usr/share/zsh/site-functions/_${BINARY}"
  else
    mkdir -p "${HOME}/.zfunc"
    printf '%s\n' "${completion}" > "${HOME}/.zfunc/_${BINARY}"
    step "Zsh completions -> ~/.zfunc/_${BINARY}"
  fi
}
{{- end}}
{{- if .Completions.Fish}}
# gpipe test: fish-completions

# Install fish completions generated by the installed binary.
#
# Falls back to the user completion directory when system install fails.
#
# Environment:
#   INSTALL_DIR, INSTALL_NAME, BINARY, USER_INSTALL - read
# Returns:
#   0 always (warns on failure)
install_fish_completions() {
  local completion
  if ! completion=$("${INSTALL_DIR}/${INSTALL_NAME}" completion fish 2>/dev/null); then
    warn "Fish completion not available from ${INSTALL_NAME}"
    warn "Binary may not support the completion subcommand"
    return 0
  fi

  if [[ "${USER_INSTALL}" == "true" ]]; then
    mkdir -p "${HOME}/.config/fish/completions"
    printf '%s\n' "${completion}" > "${HOME}/.config/fish/completions/${BINARY}.fish"
    step "Fish completions -> ~/.config/fish/completions/${BINARY}.fish"
  elif printf '%s\n' "${completion}" \
      | sudo install -m 0644 /dev/stdin \
          "/usr/share/fish/completions/${BINARY}.fish" 2>/dev/null; then
    step "Fish completions -> /usr/share/fish/completions/${BINARY}.fish"
  else
    mkdir -p "${HOME}/.config/fish/completions"
    printf '%s\n' "${completion}" > "${HOME}/.config/fish/completions/${BINARY}.fish"
    step "Fish completions -> ~/.config/fish/completions/${BINARY}.fish"
  fi
}
{{- end}}

# Ensure INSTALL_DIR is present in PATH for user installs.
#
# Appends an export line to the appropriate shell RC file(s) when
# INSTALL_DIR is not already in PATH. Uses $SHELL as a heuristic for
# the target shell since curl | bash pipelines have no reliable
# current-shell detection.
#
# Environment:
#   INSTALL_DIR, INSTALL_NAME, USER_INSTALL
#   HOME, SHELL, ZDOTDIR
# Returns:
#   0 always
manage_path() {
  if [[ "${USER_INSTALL}" != "true" ]]; then
    if ! command -v "${INSTALL_NAME}" > /dev/null 2>&1; then
      warn "${INSTALL_NAME} is not reachable via PATH"
      warn "  ${INSTALL_DIR} may need to be added to PATH manually"
    fi
    return 0
  fi

  if printf ':%s:' "${PATH}" | grep -qF ":${INSTALL_DIR}:"; then
    return 0
  fi

  local export_line="export PATH=\"${INSTALL_DIR}:\$PATH\""
  local -a modified=()

  case "${SHELL:-}" in
    */zsh)
      for _f in "${ZDOTDIR:-$HOME}/.zshrc" "${ZDOTDIR:-$HOME}/.zprofile"; do
        if [[ -f "${_f}" ]] && ! grep -qF "${INSTALL_DIR}" "${_f}" 2>/dev/null; then
          printf '\n# Added by %s installer\n%s\n' "${INSTALL_NAME}" "${export_line}" >> "${_f}"
          modified+=("${_f}")
        fi
      done ;;
    */fish)
      local fish_cfg="${HOME}/.config/fish/config.fish"
      mkdir -p "${HOME}/.config/fish"
      if ! grep -qF "${INSTALL_DIR}" "${fish_cfg}" 2>/dev/null; then
        printf '\n# Added by %s installer\nfish_add_path %s\n' \
          "${INSTALL_NAME}" "${INSTALL_DIR}" >> "${fish_cfg}"
        modified+=("${fish_cfg}")
      fi ;;
    *)
      for _f in "${HOME}/.bashrc" "${HOME}/.bash_profile" "${HOME}/.profile"; do
        if [[ -f "${_f}" ]] && ! grep -qF "${INSTALL_DIR}" "${_f}" 2>/dev/null; then
          printf '\n# Added by %s installer\n%s\n' "${INSTALL_NAME}" "${export_line}" >> "${_f}"
          modified+=("${_f}")
          break
        fi
      done ;;
  esac

  if [[ ${#modified[@]} -gt 0 ]]; then
    warn "${INSTALL_DIR} was not in PATH: added to: ${modified[*]}"
    warn "Restart your shell, or run now: ${export_line}"
  else
    warn "${INSTALL_DIR} is not in PATH. Add the following to your shell profile:"
    warn "  ${export_line}"
  fi
}


# Entry point: parse args, detect platform, download, verify, and install.
#
# Arguments:
#   $@ - command-line arguments forwarded from the shell invocation
# Returns:
#   0 on success
#   exits 1 on any failure
main() {
  USER_INSTALL=false
  NO_VERIFY=false
  INSTALL_DIR=""
  PLATFORM=""

  parse_args "$@"

  PLATFORM="$(detect_platform)"
  local asset_name
  asset_name="$(resolve_asset "${PLATFORM}")"

  setup_downloader

  local tmp_dir
  tmp_dir="$(mktemp -d)"
  trap 'rm -rf "${tmp_dir}"' EXIT

{{- if .Hooks.PreSh}}
  # gpipe test: pre-install-hook
  # Pre-install hook injected from config at generation time.
  # Available variables: GITHUB_REPO, VERSION, BINARY, INSTALL_NAME
  (
{{.Hooks.PreSh}}
  )
{{- end}}

  download_assets "${tmp_dir}" "${asset_name}"
  verify_signature "${tmp_dir}"
  verify_checksum "${tmp_dir}" "${asset_name}"
  install_binary "${tmp_dir}/${asset_name}"

{{- if .Completions.Bash}}
  install_bash_completions
{{- end}}
{{- if .Completions.Zsh}}
  install_zsh_completions
{{- end}}
{{- if .Completions.Fish}}
  install_fish_completions
{{- end}}

{{- if .Hooks.PostSh}}
  # gpipe test: post-install-hook
  # Post-install hook injected from config at generation time.
  # Available variables: GITHUB_REPO, VERSION, BINARY, INSTALL_NAME, INSTALL_DIR
  (
{{.Hooks.PostSh}}
  )
{{- end}}

  manage_path

  info "Successfully installed ${INSTALL_NAME} ${VERSION}"
}

# Guard: run main only when executed directly, not when sourced for testing.
if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
  main "$@"
fi

} # end download guard
